import type { HotdogClassificationDetails } from './HotdogClassificationDetails.type';

/** Model verdict for one image. */
export interface HotdogClassification {
  isHotdog: boolean;
  /** One short sentence explaining the verdict, shown to the user. */
  reason: string;
}

/** A classification as shown to the visitor (fresh result or history item). */
export interface HotdogClassificationRecord extends HotdogClassification {
  /** `null` for guests: the result was not saved. */
  id: string | null;
  /**
   * Short-lived signed read URLs, generated by the API from storage keys right before
   * responding (the DB only stores keys). '' when not stored (guests) or missing.
   */
  originalImageUrl: string;
  /** Small preview for lists; falls back to the original for older results without one. */
  thumbnailImageUrl: string;
  createdAt: string;
  /** `null` for results saved before v0.3 (verdict-only). */
  details: HotdogClassificationDetails | null;
}

/** Languages the model can write its answer in (matches the app locales). */
export const HOTDOG_CLASSIFICATION_LOCALE_LIST = ['en', 'ko'] as const;

export type HotdogClassificationLocale = (typeof HOTDOG_CLASSIFICATION_LOCALE_LIST)[number];

export interface ClassifyUploadedHotdogImageRequest {
  tempImagePath: string;
  /** Language of `reason` and the free-text detail fields. Defaults to `en`. */
  locale?: HotdogClassificationLocale;
}

export interface HotdogClassificationListResponse {
  /** `false` for guests (no history consent): the list is always empty. */
  isHistoryEnabled: boolean;
  hotdogClassificationList: HotdogClassificationRecord[];
}
